test("ponowne zamknięcie już zamkniętego ticketu nie wykonuje drugiego zapisu",async()=>{const repository=repo();repository.find=async()=>({...ticket,status:"CLOSED",version:1});expect((await closeTicket(42,0,user,repository)).status).toBe("CLOSED");expect(repository.close).not.toHaveBeenCalled();});
test("mutacja odrzuca brak i obcy Origin, a przyjmuje ustalony origin",()=>{for(const origin of [undefined,"https://obcy.example"]){const request=new Request("https://devdesk.example/tickets/42",{method:"POST",headers:origin?{Origin:origin}:{}});expect(()=>assertMutationOrigin(request)).toThrow(HttpFailure);}expect(()=>assertMutationOrigin(new Request("https://devdesk.example/tickets/42",{method:"POST",headers:{Origin:"https://devdesk.example"}}))).not.toThrow();});
test("Form uruchamia action, a loader jest rewalidowany po mutacji",async()=>{let current=dto(ticket),resolve!:()=>void;const pending=new Promise<void>(yes=>{resolve=yes;}),loader=vi.fn(async()=>({ticket:current}));const router=createMemoryRouter([{path:"/tickets/42",loader,action:async({request})=>{const values=await request.formData();expect(values.get("intent")).toBe("close");await pending;current={...current,status:"CLOSED",version:1};return null;},Component:TicketRoute}],{initialEntries:["/tickets/42"]});render(<RouterProvider router={router}/>);await screen.findByRole("button");await act(async()=>fireEvent.click(screen.getByRole("button")));expect(screen.getByRole("button")).toBeDisabled();expect(screen.getByRole("button")).toHaveTextContent("Zamykanie");await act(async()=>resolve());await waitFor(()=>expect(loader).toHaveBeenCalledTimes(2));expect(await screen.findByText("Status: CLOSED")).toBeVisible();router.dispose();});

